-- OWNER-ONLY APPROVAL PERMISSION ADMIN READ MODEL
create or replace function public.get_approval_permission_users()returns table(user_id uuid,full_name text,role text,active boolean,can_approve_transactions boolean,can_approve_own_entry boolean,granted_at timestamptz)language plpgsql stable security definer set search_path=public as $$declare a app_users%rowtype;begin select * into a from app_users where auth_user_id=auth.uid() and active=true;if not found or a.role<>'owner' then raise exception 'Owner authorization required';end if;return query select u.id,u.full_name,u.role,u.active,coalesce(p.can_approve_transactions,false),coalesce(p.can_approve_own_entry,false),p.granted_at from app_users u left join approval_permissions p on p.user_id=u.id where u.role in('admin','accountant') order by u.active desc,u.role,u.full_name;end;$$;revoke all on function public.get_approval_permission_users() from public,anon;grant execute on function public.get_approval_permission_users() to authenticated;
